const BASE='https://api.discogs.com',SIX_HOURS=21600;let nextUpstream=0,activeCollection=BOOTSTRAP;
function json(data,status=200){return new Response(JSON.stringify(data),{status,headers:{'Content-Type':'application/json; charset=utf-8','Cache-Control':'private, no-store','X-Content-Type-Options':'nosniff'}})}
async function upstream(path){const now=Date.now(),delay=Math.max(0,nextUpstream-now);nextUpstream=Math.max(now,nextUpstream)+2600;if(delay>20000)throw Error('Several records are loading. Please try again shortly.');if(delay)await new Promise(r=>setTimeout(r,delay));const r=await fetch(BASE+path,{headers:{'User-Agent':'MusicThatTravelsPrototype/0.2 (personal collection visualisation)','Accept':'application/json'},signal:AbortSignal.timeout(15000)});if(!r.ok){if(r.status===429)throw Error('Discogs rate limit reached. Please wait a minute and retry.');throw Error('Discogs returned '+r.status)}return r.json()}
function slim(row){const b=row.basic_information;return {instance_id:row.instance_id,id:b.id,master_id:b.master_id||0,title:b.title,year:b.year||0,thumb:b.thumb||'',cover:b.cover_image||'',artists:[...new Map((b.artists||[]).map(a=>[a.id,{id:a.id,name:a.name}])).values()],labels:(b.labels||[]).map(l=>({id:l.id,name:l.name,catno:l.catno||''})),styles:b.styles||[],genres:b.genres||[],formats:b.formats||[]}}
function release(d){return {id:d.id,country:d.country||null,released:d.released||null,year:d.year||null,credits:(d.extraartists||[]).map(c=>({name:c.name,role:c.role||''})),recorded_at:(d.companies||[]).filter(c=>c.entity_type_name==='Recorded At').map(c=>c.name),fetched_at:new Date().toISOString()}}
function master(d){return {id:d.id,year:d.year||null,title:d.title||'',fetched_at:new Date().toISOString()}}
function fresh(v){return v&&Date.now()-Date.parse(v.fetched_at)<SIX_HOURS*1000}
function getCache(){try{return typeof caches!=='undefined'?caches.default:null}catch{return null}}
async function readCache(key){try{const cache=getCache();return cache?await cache.match(key):null}catch{return null}}
async function writeCache(key,response,ctx){const task=(async()=>{try{const cache=getCache();if(cache)await cache.put(key,response)}catch{}})();if(ctx&&typeof ctx.waitUntil==='function')ctx.waitUntil(task);else await task}
async function cached(request,ctx,load){const key=new Request(new URL(request.url).origin+new URL(request.url).pathname);const found=await readCache(key);if(found){try{const d=await found.json();if(fresh(d)){if(d.entries)activeCollection=d;return json(d)}}catch{}}const result=await load();const ttl=Math.max(1,Math.min(SIX_HOURS,Math.floor((Date.parse(result.fetched_at)+SIX_HOURS*1000-Date.now())/1000)));await writeCache(key,new Response(JSON.stringify(result),{headers:{'Content-Type':'application/json','Cache-Control':'public,max-age='+ttl}}),ctx);return json(result)}
function linkedVideos(videos,limit=12){return (Array.isArray(videos)?videos:[]).flatMap(v=>{if(v.embed===false)return [];try{const u=new URL(v.uri);if(u.protocol!=='https:'&&u.protocol!=='http:')return [];const host=u.hostname.toLowerCase();let id=host==='youtu.be'?u.pathname.slice(1):['youtube.com','www.youtube.com','m.youtube.com'].includes(host)?(u.searchParams.get('v')||u.pathname.match(/^\/(?:embed|shorts)\/([\w-]{11})$/)?.[1]):null;return /^[\w-]{11}$/.test(id||'')?[{id,title:String(v.title||'Listen to this record').slice(0,240)}]:[]}catch{return []}}).filter((v,i,a)=>a.findIndex(x=>x.id===v.id)===i).slice(0,limit)}
function orderedRecord(d){
 const videos=linkedVideos(d.videos,200),tracks=[];
 const flatten=rows=>{for(const t of rows||[]){if(t.sub_tracks?.length)flatten(t.sub_tracks);else if(t.type_!=='heading'&&t.title&&(t.position||t.type_==='track'))tracks.push({title:String(t.title),position:String(t.position||'')})}};flatten(d.tracklist);
 const normalize=s=>String(s).normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^\p{L}\p{N}]+/gu,' ').trim();
 const album=normalize(d.title),full=videos.find(v=>/\b(full album|full lp|complete album)\b/i.test(v.title)&&album&&(' '+normalize(v.title)+' ').includes(' '+album+' '));
 if(full)return {videos:[full],coverage:{fullAlbum:true,total:tracks.length,matched:tracks.length,missing:0}};
 const used=new Set(),ordered=[];
 for(const track of tracks){const name=normalize(track.title);if(!name)continue;const candidates=videos.map((v,i)=>({v,i,text:normalize(v.title)})).filter(({v,i,text})=>!used.has(i)&&(text===name||(name.length>=4&&(' '+text+' ').includes(' '+name+' '))||v.title.split(/[-–—|:]/).some(part=>normalize(part)===name))).sort((a,b)=>(a.text.length-name.length)-(b.text.length-name.length));if(candidates.length){const {v,i}=candidates[0];used.add(i);ordered.push({...v,position:track.position,trackTitle:track.title})}}
 return {videos:ordered,coverage:{fullAlbum:false,total:tracks.length,matched:ordered.length,missing:Math.max(0,tracks.length-ordered.length)}};
}
